import fs from 'node:fs';
import {createHash} from 'node:crypto';

// Generated by a separate native Xiaohe TTS connection. Never inject SayHello
// into a session that is awaiting a function result: it can replace that turn.
let clips;
export function loadToolStartClips() {
  if(clips)return clips;
  const root=new URL('./assets/',import.meta.url);
  const manifest=JSON.parse(fs.readFileSync(new URL('tool-start-provenance.json',root),'utf8'));
  if(manifest.provider!=='seeduplex'||manifest.voice!=='xiaohe'||manifest.sampleRate!==24000||manifest.format!=='pcm16le')throw Error('Invalid tool notice audio format');
  const loaded={};
  for(const key of ['memory','web','other']){
    const spec=manifest.clips[key],pcm=fs.readFileSync(new URL(`tool-start-${key}.pcm`,root));
    if(!spec?.text||pcm.length!==spec.bytes||pcm.length%2||createHash('sha256').update(pcm).digest('hex')!==spec.sha256)throw Error('Tool notice audio hash mismatch');
    loaded[key]={...spec,pcm,sampleRate:24000,source:'cached-native-tool-start'};
  }
  clips=loaded;return clips;
}
export function toolStartClip(call,loaded=loadToolStartClips()) {
  if(['end_call','cancel_task','delegate_to_v','process'].includes(call.name))return null;
  const name=call.name==='openclaw_tool'?call.args?.tool:call.name;
  if(['end_call','cancel_task','delegate_to_v','process'].includes(name))return null;
  return loaded[name==='memory_search'?'memory':['web_search','web_fetch'].includes(name)?'web':'other'];
}
